def minimumSum(grid):
    n = len(grid)
    m = len(grid[0])
    INF = float('inf')

    def area(r1, r2, c1, c2):
        # bounding-box area of the ones in [r1,r2) x [c1,c2); INF if there are none
        minr = minc = INF
        maxr = maxc = -1
        for i in range(r1, r2):
            row = grid[i]
            for j in range(c1, c2):
                if row[j]:
                    if i < minr: minr = i
                    if i > maxr: maxr = i
                    if j < minc: minc = j
                    if j > maxc: maxc = j
        if maxr < 0:
            return INF
        return (maxr - minr + 1) * (maxc - minc + 1)

    best = INF
    # Three non-overlapping rectangles covering all ones are always guillotine
    # separable, so enumerate the possible two-cut layouts.
    # Two horizontal cuts.
    for i in range(1, n):
        for j in range(i + 1, n):
            best = min(best, area(0, i, 0, m) + area(i, j, 0, m) + area(j, n, 0, m))
    # Two vertical cuts.
    for i in range(1, m):
        for j in range(i + 1, m):
            best = min(best, area(0, n, 0, i) + area(0, n, i, j) + area(0, n, j, m))
    # One horizontal cut, the other half split by a vertical cut.
    for i in range(1, n):
        for j in range(1, m):
            best = min(best, area(0, i, 0, m) + area(i, n, 0, j) + area(i, n, j, m))
            best = min(best, area(i, n, 0, m) + area(0, i, 0, j) + area(0, i, j, m))
    # One vertical cut, the other half split by a horizontal cut.
    for j in range(1, m):
        for i in range(1, n):
            best = min(best, area(0, n, 0, j) + area(0, i, j, m) + area(i, n, j, m))
            best = min(best, area(0, n, j, m) + area(0, i, 0, j) + area(i, n, 0, j))
    return best
